public class PublicationSafetyDemo {
    private int normalValue = 0;
    private volatile boolean ready = false;

    public void writerThread() {
        normalValue = 42; // (1)
        ready = true;     // (2) Volatile write establishes happens-before edge
    }

    public void readerThread() {
        if (ready) {      // (3) Volatile read
            // (4) Guaranteed to see normalValue == 42 due to transitivity
            int v = normalValue; 
            assert v == 42;
        }
    }
}
